function render(){refreshShell();const header=el('#study-timer-slot');if(header)header.innerHTML=timerBadge();const routes={home:renderHome,plan:renderPlan,learning:renderLearning,session:renderSession,game:renderGame,review:renderReview,library:renderLibrary,settings:renderSettings,sim510:renderSim510,sim324:renderSim324,sim510w7:renderSim510W7,sim324w7:renderSim324W7};el('#app').innerHTML=routes[app.route]?.()||renderHome();}
