function timerPlan(key){const period=String(key||'').split('|')[1],current=state.timer;if(current?.sessionKey===key&&current.r5Plan)return current.r5Plan;const work=period==='evening'?(Number(state.prefs.nightBlock)===90?90:45):(Number(state.prefs.dayBlock)===90?90:60);return {work,rest:period==='evening'?10:15,blocks:period==='evening'?90/work:['morning','afternoon'].includes(period)?180/work:Infinity};}
