function downloadUpdateBackup(){try{const text=JSON.stringify(makeUpdateBackup());const file=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=`ufms-backup-atualizacao-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('Backup preparado. Confira o arquivo na pasta de downloads antes de atualizar.')}catch(e){notify('Não foi possível preparar o backup: '+e.message)}}
function validSavedTimer(t){return plain(t)&&t.schema===2&&['work','break','done'].includes(t.mode)&&Number.isFinite(t.remaining)&&t.remaining>=0&&t.remaining<=86400&&Number.isInteger(t.completedBlocks)&&t.completedBlocks>=0&&Number.isInteger(t.periodBlocks)&&t.periodBlocks>=0&&(!t.sessionKey||safeKey(t.sessionKey))}
function pausedTimer(t){return {...initial().timer,...t,active:false,lastTick:null,manuallyPaused:true}}
function validateUpdate(obj){const u=obj.update;if(!plain(u)||!plain(u.sessionTimers)||Object.keys(u.sessionTimers).length>10000||!Object.entries(u.sessionTimers).every(([k,t])=>safeKey(k)&&validSavedTimer(t))||!validSavedTimer(u.timer))throw Error('Cronômetros inválidos no backup.');if(!plain(obj.records)||Object.keys(obj.records).length>100000||!Object.entries(obj.records).every(([k,r])=>validRecord(k,r)))throw Error('Registros inválidos no backup.');return u}
function applyUpdateBackup(obj){const u=validateUpdate(obj);const changed=mergeRecords(obj.records);if([60,90].includes(obj.data?.prefs?.dayBlock))state.prefs.dayBlock=obj.data.prefs.dayBlock;if([45,90].includes(obj.data?.prefs?.nightBlock))state.prefs.nightBlock=obj.data.prefs.nightBlock;for(const [k,t] of Object.entries(u.sessionTimers)){if(!own(state.sessionTimers,k))state.sessionTimers[k]=pausedTimer(t)}if(!state.timer.sessionKey||state.timer.completedBlocks===0&&state.timer.periodBlocks===0&&!state.timer.active){state.timer=pausedTimer(u.timer)}save();return changed}
async function importJson(file){try{const obj=JSON.parse(await file.text());if(obj.format!=='ufms-estudos'||!obj.data||!Array.isArray(obj.data.events)||![1,2,3].includes(obj.version))throw Error('Formato inválido ou versão de backup não suportada.');if(obj.version===3){validateUpdate(obj);if(!confirm('Restaurar este backup e combinar com os registros atuais? Guarde uma cópia antes de continuar.'))return;applyUpdateBackup(obj)}else if(obj.version===2&&obj.records)mergeRecords(obj.records);else mergeRemote(obj.data);notify('Dados combinados. Confira seu progresso.');render()}catch(e){notify('Erro ao importar: '+e.message)}}
function mergeRemote(remote){const map=new Map([...state.events,...(remote.events||[])].map(e=>[e.id,e]));state.events=Array.from(map.values()).sort((a,b)=>a.t-b.t);
for(const [k,v] of Object.entries(remote.notes||{})){if(!state.notes[k]||(v.updatedAt||0)>(state.notes[k].updatedAt||0))state.notes[k]=v}
for(const d of remote.documents||[]){const i=state.documents.findIndex(x=>x.id===d.id);if(i<0)state.documents.push(d);else if((d.updatedAt||0)>(state.documents[i].updatedAt||0))state.documents[i]=d}
for(const [k,v] of Object.entries(remote.videos||{})){if(!state.videos[k]&&typeof v==='string')state.videos[k]=v}
if(!state.prefs.displayName&&remote.prefs?.displayName)state.prefs.displayName=remote.prefs.displayName;save()}
