function handleSim324W7Click(e){const b=e.target.closest('[data-sim324w7-act],[data-sim324w7-choice],[data-sim324w7-jump]');if(!b)return false;const a=b.dataset.sim324w7Act,s=sim324W7State();if(a==='start'||a==='restart'){if(a==='restart'&&!confirm('Iniciar nova tentativa? O resultado anterior permanece no histórico, mas suas marcações serão substituídas.'))return true;if(state.timer.active){tick();state.timer.active=false;state.timer.manuallyPaused=true;state.timer.lastTick=null}state.sim324w7={deadline:Date.now()+4*3600*1000,index:0,answers:{},finished:false};save();render();return true}if(!s||s.finished)return true;if(sim324W7Remaining()===0){sim324W7Finish();return true}if(b.dataset.sim324w7Choice!==undefined)s.answers[s.index]=Number(b.dataset.sim324w7Choice);else if(b.dataset.sim324w7Jump!==undefined)s.index=Number(b.dataset.sim324w7Jump);else if(a==='prev')s.index=Math.max(0,s.index-1);else if(a==='next')s.index=Math.min(59,s.index+1);else if(a==='clear')delete s.answers[s.index];else if(a==='finish'){if(confirm(`Entregar a prova? ${Object.keys(s.answers).length}/60 respondidas. A correção será exibida e a tentativa encerrada.`))sim324W7Finish();return true}save();render();return true}

// R5: quiz selection, accessible navigation, deliberate breaks, legislation and optional QR pairing.
function beginQuiz(l,s,retry=false){
 let questions=s.questions;
 if(s.r5){
  const old=questions.slice(0,s.originalCount),fresh=questions.slice(s.originalCount),previous=new Set(retry?(app.quiz?.questions||[]).map(q=>q.id):[]);
  const seen=new Set(state.events.filter(e=>e.type==='answer'&&e.lessonId===l.id&&e.sectionId===s.id).map(e=>e.questionId));
  if(retry){const pool=shuffleGame(questions).sort((a,b)=>Number(previous.has(a.id))-Number(previous.has(b.id))||Number(seen.has(a.id))-Number(seen.has(b.id)));questions=pool.slice(0,5)}
  else{const authored=q=>q.id.endsWith('_manual')||q.kind==='application',manual=shuffleGame(fresh.filter(authored)),other=shuffleGame(fresh.filter(q=>!authored(q))).sort((a,b)=>Number(a.kind==='cloze')-Number(b.kind==='cloze')||Number(seen.has(a.id))-Number(seen.has(b.id)));const nOld=manual.length>=2?2:Math.min(3,old.length);questions=shuffleGame([...old.slice(0,nOld),...manual,...other,...old.slice(nOld)].slice(0,5))}
 }
 app.quiz={index:0,answers:[],finished:false,questions};
}
